CREATE TABLE IF NOT EXISTS public.affiliate_referrals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE, affiliate_id uuid NOT NULL REFERENCES public.affiliates(id) ON DELETE CASCADE, driver_id uuid NOT NULL REFERENCES public.drivers(id) ON DELETE RESTRICT, sale_id uuid REFERENCES public.sales(id) ON DELETE SET NULL, referred_at timestamptz NOT NULL DEFAULT now(), status text NOT NULL DEFAULT 'LEAD', source text, notes text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(affiliate_id, driver_id));